#define MAX_TOKEN_LEN 512
#define MAX_PAYLOAD_LEN 256
#define HMAC_LEN 32
#define MAX_SESSIONS 64

typedef struct {
    char username[64];
    uint32_t role;  /* 0=guest, 1=user, 2=admin */
    uint64_t expires;
    uint8_t active;
} session_t;

static session_t sessions[MAX_SESSIONS];
static const uint8_t server_key[32] = {
    0x4a,0x7b,0x3c,0x9d,0x2e,0x1f,0x8a,0x6b,
    0x5c,0x0d,0x9e,0x7f,0x3a,0x2b,0x1c,0x8d,
    0x6e,0x4f,0x0a,0x9b,0x5c,0x3d,0x7e,0x1f,
    0x8a,0x2b,0x6c,0x4d,0x0e,0x9f,0x3a,0x5b
};

/* Simple HMAC-like construction (simplified for demonstration) */
static void compute_hmac(const uint8_t *data, size_t data_len,
                         const uint8_t *key, uint8_t *out) {
    uint8_t pad[64];
    memset(pad, 0x36, sizeof(pad));
    for (int i = 0; i < 32; i++) pad[i] ^= key[i];

    /* Simple hash: XOR-fold with rotation */
    uint8_t state[32];
    memset(state, 0, sizeof(state));
    for (size_t i = 0; i < sizeof(pad); i++)
        state[i % 32] ^= pad[i];
    for (size_t i = 0; i < data_len; i++) {
        state[i % 32] ^= data[i];
        state[(i+1) % 32] = (state[(i+1) % 32] << 1) | (state[(i+1) % 32] >> 7);
    }
    memcpy(out, state, 32);
}

/* Base64url decode - returns decoded length, or -1 on error */
static int b64url_decode(const char *src, size_t src_len,
                         uint8_t *dst, size_t dst_size) {
    static const int8_t table[256] = {
        [0 ... 255] = -1,
        ['A'] = 0,  ['B'] = 1,  ['C'] = 2,  ['D'] = 3,
        ['E'] = 4,  ['F'] = 5,  ['G'] = 6,  ['H'] = 7,
        ['I'] = 8,  ['J'] = 9,  ['K'] = 10, ['L'] = 11,
        ['M'] = 12, ['N'] = 13, ['O'] = 14, ['P'] = 15,
        ['Q'] = 16, ['R'] = 17, ['S'] = 18, ['T'] = 19,
        ['U'] = 20, ['V'] = 21, ['W'] = 22, ['X'] = 23,
        ['Y'] = 24, ['Z'] = 25, ['a'] = 26, ['b'] = 27,
        ['c'] = 28, ['d'] = 29, ['e'] = 30, ['f'] = 31,
        ['g'] = 32, ['h'] = 33, ['i'] = 34, ['j'] = 35,
        ['k'] = 36, ['l'] = 37, ['m'] = 38, ['n'] = 39,
        ['o'] = 40, ['p'] = 41, ['q'] = 42, ['r'] = 43,
        ['s'] = 44, ['t'] = 45, ['u'] = 46, ['v'] = 47,
        ['w'] = 48, ['x'] = 49, ['y'] = 50, ['z'] = 51,
        ['0'] = 52, ['1'] = 53, ['2'] = 54, ['3'] = 55,
        ['4'] = 56, ['5'] = 57, ['6'] = 58, ['7'] = 59,
        ['8'] = 60, ['9'] = 61, ['-'] = 62, ['_'] = 63
    };

    size_t out_len = (src_len * 3) / 4;
    if (out_len > dst_size) return -1;

    size_t i = 0, j = 0;
    while (i < src_len) {
        uint32_t acc = 0;
        int bits = 0;
        for (int k = 0; k < 4 && i < src_len; k++, i++) {
            if (src[i] == '=') continue;
            int8_t val = table[(unsigned char)src[i]];
            if (val < 0) return -1;
            acc = (acc << 6) | val;
            bits += 6;
        }
        while (bits >= 8) {
            bits -= 8;
            if (j < dst_size)
                dst[j++] = (acc >> bits) & 0xFF;
        }
    }
    return (int)j;
}

/* Parse token: header.payload.signature */
static int parse_token(const char *token, size_t token_len,
                       uint8_t *payload_out, size_t *payload_len,
                       uint8_t *sig_out) {
    const char *first_dot = memchr(token, '.', token_len);
    if (!first_dot) return -1;

    size_t header_len = first_dot - token;
    const char *after_first = first_dot + 1;
    size_t remaining = token_len - header_len - 1;

    const char *second_dot = memchr(after_first, '.', remaining);
    if (!second_dot) return -1;

    size_t payload_b64_len = second_dot - after_first;
    const char *sig_start = second_dot + 1;
    size_t sig_b64_len = token_len - header_len - 1 - payload_b64_len - 1;

    int dec_len = b64url_decode(after_first, payload_b64_len,
                                payload_out, MAX_PAYLOAD_LEN);
    if (dec_len < 0) return -1;
    *payload_len = (size_t)dec_len;

    uint8_t sig_buf[64];
    int sig_dec_len = b64url_decode(sig_start, sig_b64_len, sig_buf, sizeof(sig_buf));
    if (sig_dec_len < 0) return -1;

    /* Vulnerability: signed comparison allows negative sig_dec_len to bypass */
    /* Actually sig_dec_len is already checked >= 0 above, real bug is below */
    if (sig_dec_len > HMAC_LEN) return -1;
    memcpy(sig_out, sig_buf, sig_dec_len);

    return 0;
}

/* Verify token signature - THE VULNERABILITY IS HERE */
static int verify_token(const char *token, size_t token_len,
                        uint8_t *payload_out, size_t *payload_len) {
    uint8_t signature[HMAC_LEN];
    memset(signature, 0, sizeof(signature));

    if (parse_token(token, token_len, payload_out, payload_len, signature) != 0)
        return -1;

    /* Compute expected HMAC over header.payload (everything before last dot) */
    const char *last_dot = NULL;
    for (int i = (int)token_len - 1; i >= 0; i--) {
        if (token[i] == '.') { last_dot = &token[i]; break; }
    }
    if (!last_dot) return -1;

    size_t signed_len = last_dot - token;
    uint8_t expected[HMAC_LEN];
    compute_hmac((const uint8_t *)token, signed_len, server_key, expected);

    /* Timing-safe comparison... but with a critical flaw */
    /* sig_dec_len from parse_token could be LESS than HMAC_LEN (e.g., 0 bytes) */
    /* We only compare up to what was decoded, rest of signature buffer is zeros */
    /* If attacker provides empty signature, memcpy copies 0 bytes, signature */
    /* buffer remains all-zeros, and we compare 32 zero bytes vs expected HMAC */
    /* This comparison will fail... UNLESS the attacker can make expected = 0s */

    /* ACTUAL BUG: The comparison length uses the DECODED signature length */
    /* which can be shorter than HMAC_LEN. parse_token copies sig_dec_len bytes */
    /* but signature buffer was zeroed. However the REAL issue is: */

    /* We compare byte-by-byte but return success if first sig_dec_len bytes match */
    int sig_len = 0;
    for (const char *p = last_dot + 1; *p && p < token + token_len; p++) sig_len++;
    int decoded_sig_len = (sig_len * 3) / 4;  /* approximate decoded length */

    /* BUG: if decoded_sig_len is 0 (empty signature segment), diff stays 0 */
    volatile uint8_t diff = 0;
    for (int i = 0; i < decoded_sig_len; i++) {
        diff |= signature[i] ^ expected[i];
    }

    return diff == 0 ? 0 : -1;
}

static int extract_claims(const uint8_t *payload, size_t payload_len,
                          char *username, size_t uname_size,
                          uint32_t *role, uint64_t *expires) {
    /* Simple binary format: [1 byte uname_len][uname][4 bytes role][8 bytes expires] */
    if (payload_len < 1) return -1;
    uint8_t uname_len = payload[0];
    if (uname_len == 0 || (size_t)uname_len + 13 > payload_len) return -1;
    if ((size_t)uname_len >= uname_size) return -1;

    memcpy(username, &payload[1], uname_len);
    username[uname_len] = '\0';

    memcpy(role, &payload[1 + uname_len], 4);
    memcpy(expires, &payload[1 + uname_len + 4], 8);

    return 0;
}

static int create_session(const char *username, uint32_t role, uint64_t expires) {
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (!sessions[i].active) {
            strncpy(sessions[i].username, username, sizeof(sessions[i].username) - 1);
            sessions[i].username[sizeof(sessions[i].username) - 1] = '\0';
            sessions[i].role = role;
            sessions[i].expires = expires;
            sessions[i].active = 1;
            return i;
        }
    }
    return -1;
}

static void handle_auth_request(int client_fd) {
    char buf[MAX_TOKEN_LEN + 1];
    ssize_t nread = read(client_fd, buf, MAX_TOKEN_LEN);
    if (nread <= 0) return;
    buf[nread] = '\0';

    /* Strip trailing newline */
    if (nread > 0 && buf[nread-1] == '\n') buf[--nread] = '\0';

    uint8_t payload[MAX_PAYLOAD_LEN];
    size_t payload_len = 0;

    if (verify_token(buf, (size_t)nread, payload, &payload_len) != 0) {
        const char *resp = "AUTH_FAILED\n";
        write(client_fd, resp, strlen(resp));
        return;
    }

    char username[64];
    uint32_t role;
    uint64_t expires;

    if (extract_claims(payload, payload_len, username, sizeof(username),
                       &role, &expires) != 0) {
        const char *resp = "INVALID_TOKEN\n";
        write(client_fd, resp, strlen(resp));
        return;
    }

    uint64_t now = (uint64_t)time(NULL);
    if (expires < now) {
        const char *resp = "TOKEN_EXPIRED\n";
        write(client_fd, resp, strlen(resp));
        return;
    }

    int sid = create_session(username, role, expires);
    if (sid < 0) {
        const char *resp = "NO_SESSIONS\n";
        write(client_fd, resp, strlen(resp));
        return;
    }

    char resp[128];
    snprintf(resp, sizeof(resp), "AUTH_OK session=%d role=%u\n", sid, role);
    write(client_fd, resp, strlen(resp));
}

int main(void) {
    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) { perror("socket"); return 1; }

    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in addr = {
        .sin_family = AF_INET,
        .sin_port = htons(9090),
        .sin_addr.s_addr = htonl(INADDR_LOOPBACK)
    };

    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind"); close(server_fd); return 1;
    }

    if (listen(server_fd, 16) < 0) {
        perror("listen"); close(server_fd); return 1;
    }

    printf("Auth server listening on 127.0.0.1:9090\n");

    while (1) {
        int client_fd = accept(server_fd, NULL, NULL);
        if (client_fd < 0) continue;
        handle_auth_request(client_fd);
        close(client_fd);
    }

    return 0;
}
